        },
        v if v.is_f64() => ProstValue {
            kind: Some(Kind::NumberValue(v.as_f64().unwrap())),
        },
        v if v.is_i64() => ProstValue {
            kind: Some(Kind::NumberValue(v.as_i64().unwrap() as f64)),
