        v if v.is_u64() => ProstValue {
            kind: Some(Kind::NumberValue(v.as_u64().unwrap() as f64)),
200→        },
        v if v.is_array() => ProstValue {
            kind: Some(Kind::ListValue(ProstListValue {
                values: v
                    .as_array()
